    int counter;

    [Parameter] public string Subject { get; set; }
    [Parameter] public int Year { get; set; }
    string href;

    [CascadingParameter]
    private Task<AuthenticationState> AuthenticationStateTask { get; set; }

    public static ExamQuestionsViewModel Data { get; set; }

    protected override async Task OnInitializedAsync()
    {
        counter = 1;
        Data = await service.LoadExamByExamTypeAndYearAsync(Subject, Year);
        Data.YearOfCreation = Year;
        Data.ExamType = Subject;
    }

    private async Task RedirectToAsync(string path)
    {
        await JS.InvokeVoidAsync("clientFunctions.RedirectTo", path);
    }

    private async Task Solve()
    {
        counter = 0;
        var authState = await AuthenticationStateTask;
        var examResultId = await this.service.SolveExamAsync(Data, authState.User.Identity.Name);
        
        href = $"/AllExams/{Subject}/{Year}/{examResultId}";
        await this.RedirectToAsync($"/AllExams/{Subject}/{Year}/{examResultId}");
    }

    [JSInvokable(identifier: "SelectAnswer")]
    public static Task Select(int questionId, int answerId)
    {
        Data.Questions[questionId - 1].Answers[answerId].IsSelected = true;
        return Task.CompletedTask;
    }


